{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — A reflective approach to whole-life support</title>
  <meta name="description" content="Gentle, evidence-informed integrative sessions that respect your rhythm. Intensive offerings and guided pathways tailored to you." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="layout-clinic">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/">Home</a>
        <a href="services.html">Offerings</a>
        <a href="conditions.html">Ailments</a>
        <a href="approach.html">Method</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">About</a>
        <a href="book.html" class="cta">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="wrap hero-inner">
        <div class="hero-text">
          <h1 class="title">A listening practice for your whole day-to-day</h1>
          <p class="lead">We blend clinical insight with restorative practices to support transitions, build resilience, and ease daily tensions. Personalized intensives and follow-up support designed for modern life.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn whisper" href="about.html">Meet our approach</a>
          </div>
        </div>
        <div class="hero-pattern" aria-hidden="true">
          <svg class="shape" viewBox="0 0 400 320" preserveAspectRatio="xMidYMid slice">
            <defs>
              <pattern id="p" width="60" height="60" patternUnits="userSpaceOnUse" patternTransform="rotate(15)">
                <rect width="60" height="60" fill="rgba(255,255,255,0.02)"></rect>
                <path d="M0 30 L30 0 M30 60 L60 30" stroke="rgba(255,255,255,0.05)" stroke-width="1"/>
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#p)"></rect>
          </svg>
        </div>
      </div>
    </section>

    <!-- WHAT TO EXPECT (includes Mood-to-Method selector) -->
    <section class="what-to-expect" id="what">
      <div class="wrap">
        <h2>What to expect in an intensive</h2>
        <p class="muted">Each pathway is created from an intake conversation, brief assessment, and a co-created plan. We do not promise cures; we offer structured support and education to help your system respond differently.</p>

        <div class="mood-method card">
          <div class="mood-controls">
            <label class="label">Choose how you feel right now</label>
            <div class="moods" role="tablist" aria-label="Mood to method selector">
              <button class="mood" data-key="tired">Tired</button>
              <button class="mood" data-key="wound">Wound</button>
              <button class="mood" data-key="overwhelmed">Overwhelmed</button>
              <button class="mood" data-key="ready">Ready to change</button>
            </div>
          </div>

          <div class="method-preview" id="methodPreview">
            <h3 class="method-title">Personalized Rhythm Intensive</h3>
            <p class="method-desc">A focused session blending somatic calibration, lifestyle mapping, and targeted home practices—designed to create a clear first phase of change.</p>
            <div class="method-actions">
              <a id="methodCta" class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
              <a class="btn" href="approach.html">Learn about the method</a>
            </div>
          </div>
        </div>

      </div>
    </section>

    <!-- GALLERY -->
    <section class="gallery" id="gallery">
      <div class="wrap">
        <h2>Scenes from our work</h2>
        <p class="muted">Calm spaces, quiet practices, and structured encounters. The setting is crafted to make focused change possible.</p>
        <div class="thumbs">
          <div class="thumb"> <svg viewBox="0 0 100 60" class="svgbox" aria-hidden="true"><rect width="100" height="60" rx="8" fill="#f5f9f6"/><text x="50" y="36" font-size="10" text-anchor="middle" fill="#7b8c83">Consultation</text></svg></div>
          <div class="thumb"> <svg viewBox="0 0 100 60" class="svgbox" aria-hidden="true"><rect width="100" height="60" rx="8" fill="#fff8f3"/><text x="50" y="36" font-size="10" text-anchor="middle" fill="#9b836f">Somatic Work</text></svg></div>
          <div class="thumb"> <svg viewBox="0 0 100 60" class="svgbox" aria-hidden="true"><rect width="100" height="60" rx="8" fill="#f3f6ff"/><text x="50" y="36" font-size="10" text-anchor="middle" fill="#6b77a3">Planning</text></svg></div>
        </div>
      </div>
    </section>

    <!-- OBJECTIONS / FAQs -->
    <section class="objections" id="faq">
      <div class="wrap">
        <h2>Questions people bring</h2>
        <ul class="faqs">
          <li><strong>Is this scientific-backed?</strong> We combine clinical knowledge and practical modalities; recommendations are educational and individualized.</li>
          <li><strong>Will one intensive be enough?</strong> Intensives are a strong start; many clients follow with short check-ins or a tailored package to sustain gains.</li>
          <li><strong>Do you offer remote visits?</strong> Yes—some pathways adapt well to remote sessions.</li>
        </ul>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta" id="cta">
      <div class="wrap">
        <div class="cta-inner">
          <h2>Begin a focused course of care</h2>
          <p class="muted">Schedule an intake to map a plan. Sessions, education, and guided practices to support measurable change.</p>
          <div class="cta-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn outline" href="contact.html">Ask a question</a>
          </div>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-left">
        <strong>{{BUSINESS_NAME}}</strong>
        <div class="muted">Serving {{CITY}}, {{STATE}}</div>
      </div>
      <div class="foot-right">
        <div class="muted">Contact</div>
        <a href="tel:{{PHONE}}">{{PHONE}}</a>
        <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
