{"path":"assets/css/styles.css","content":"/* Core styles for clinic_modern, mystic_modern voice */
:root{
  --bg:#0f1720;
  --card:#0f1b16;
  --accent:#8fd3c7;
  --accent-2:#7a9cba;
  --muted:rgba(255,255,255,0.6);
  --glass:rgba(255,255,255,0.04);
  --radius:12px;
  font-family: Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
}
*{box-sizing:border-box}
body{margin:0;background:linear-gradient(180deg,#071018 0%,#0c1714 100%);color:#e9f6f0;line-height:1.45}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{background:transparent;padding:18px 0;position:sticky;top:0;z-index:10}
.brand{font-weight:700;color:var(--accent);text-decoration:none;font-size:18px}
.main-nav{display:flex;gap:14px;align-items:center}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.main-nav a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#04201b}
.hero{padding:48px 0}
.hero-inner{display:flex;gap:28px;align-items:center}
.hero-text{flex:1}
.title{font-size:34px;margin:0 0 10px;color:#fff}
.lead{color:var(--muted);max-width:55ch}
.hero-actions{margin-top:18px;display:flex;gap:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;color:inherit;border:1px solid transparent;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#05211b}
.btn.whisper{background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted)}
.btn.outline{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted)}
.hero-pattern{width:320px;height:220px;flex:0 0 320px;border-radius:16px;overflow:hidden;background:linear-gradient(135deg,#05100d33,transparent)}
.shape{width:100%;height:100%}
.what-to-expect{padding:28px 0}
.card{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:18px;border-radius:var(--radius);display:flex;gap:18px;align-items:flex-start}
.mood-controls{width:220px}
.label{font-size:13px;color:var(--muted);display:block;margin-bottom:8px}
.moods{display:flex;flex-direction:column;gap:8px}
.mood{padding:10px;border-radius:10px;background:var(--glass);color:var(--muted);border:1px solid rgba(255,255,255,0.02);cursor:pointer}
.mood.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#04211b}
.method-preview{flex:1}
.method-title{margin:0 0 8px;font-size:20px}
.method-desc{color:var(--muted);margin:0 0 12px}
.method-actions .btn{margin-right:8px}
.gallery{padding:28px 0}
.thumbs{display:flex;gap:14px}
.thumb{width:30%;background:var(--glass);padding:12px;border-radius:10px}
.svgbox{width:100%;height:60px}
.objections{padding:28px 0}
.faqs{list-style:none;padding:0;margin:0;display:grid;gap:12px}
.faqs li{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}
.cta{padding:32px 0}
.cta-inner{display:flex;justify-content:space-between;align-items:center;gap:20px}
.site-footer{border-top:1px solid rgba(255,255,255,0.02);padding:18px 0;margin-top:48px}
.foot-left{float:left}
.foot-right{float:right;text-align:right}
.muted{color:var(--muted)}
/* Pricing comparator styles (used on pricing page and optionally inserted) */
.pricing-compare{display:flex;gap:18px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:18px;border-radius:12px;align-items:center}
.toggle{display:inline-flex;background:rgba(255,255,255,0.02);padding:6px;border-radius:999px}
.toggle button{background:transparent;border:none;color:var(--muted);padding:8px 12px;border-radius:999px;cursor:pointer}
.toggle button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#04211b}
.pricing-list{display:flex;gap:12px;margin-left:18px}
.price-card{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px;width:180px;text-align:center}
.price{font-size:22px;font-weight:700}
.price-sub{font-size:12px;color:var(--muted)}
/* Responsive */
@media (max-width:900px){
  .hero-inner{flex-direction:column}
  .hero-pattern{width:100%;height:170px}
  .cta-inner{flex-direction:column;align-items:flex-start}
  .wrap{padding:20px}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mood-to-Method selector
  const moods = document.querySelectorAll('.mood');
  const methodTitle = document.querySelector('.method-title');
  const methodDesc = document.querySelector('.method-desc');
  const methodCta = document.getElementById('methodCta');

  const approaches = {
    tired:{
      title:'Gentle Reset Session',
      desc:'Short, restorative protocol focused on sleep hygiene, nervous-system regulation, and a compact home routine to restore energy reserve.',
      cta:'Book a Reset Session'
    },
    wound:{
      title:'Repair-Focused Intensive',
      desc:'A paced intake and targeted care plan emphasizing trauma-informed pacing, somatic resourcing, and relational safety strategies.',
      cta:'Schedule Repair Intensive'
    },
    overwhelmed:{
      title:'Clarity & Boundaries Plan',
      desc:'A structured consult to map stressors, create simple boundary experiments, and practice short stabilization tools you can use daily.',
      cta:'Start a Clarity Session'
    },
    ready:{
      title:'Transformation Intensive',
      desc:'An in-depth working session with measurable targets, followed by short follow-ups to translate shifts into routine change.',
      cta:'Book a Transformation Intensive'
    }
  };

  function setActiveMood(key, btn){
    moods.forEach(b=>b.classList.remove('active'));
    btn.classList.add('active');
    const a = approaches[key];
    if(!a) return;
    // morph text with simple fade
    methodTitle.style.opacity = 0;
    methodDesc.style.opacity = 0;
    methodCta.style.opacity = 0;
    setTimeout(()=>{
      methodTitle.textContent = a.title;
      methodDesc.textContent = a.desc;
      methodCta.textContent = a.cta + ' — {{PRIMARY_CTA_LABEL}}';
      methodCta.setAttribute('href','{{PRIMARY_CTA_URL}}');
      methodTitle.style.opacity = 1;
      methodDesc.style.opacity = 1;
      methodCta.style.opacity = 1;
    },220);
    // small background pulse
    const card = document.querySelector('.mood-method');
    card.animate([{boxShadow:'0 0 0 0 rgba(143,211,199,0.1)'},{boxShadow:'0 20px 40px -20px rgba(143,211,199,0.05)'}],{duration:420,fill:'forwards'});
  }

  moods.forEach(btn=>{
    btn.addEventListener('click',()=>setActiveMood(btn.getAttribute('data-key'),btn));
  });
  // default
  const defaultBtn = document.querySelector('.mood[data-key="tired"]');
  if(defaultBtn) setActiveMood('tired',defaultBtn);

  // Pricing comparator (this page includes styles; support for other pages)
  const pricingAreas = document.querySelectorAll('.pricing-compare');
  // Example data for site-global usage
  const pricingData = {
    monthly:[
      {name:'Pulse Plan',price:145,sub:'per month — ongoing support'},
      {name:'Rhythm Intensive',price:420,sub:'per month — single intensive'},
      {name:'Core Reset',price:85,sub:'per month — short follow-ups'}
    ],
    package:[
      {name:'Pulse Plan',price:410,sub:'3-month bundle — save 15%'},
      {name:'Rhythm Intensive',price:990,sub:'one intensive + 2 check-ins'},
      {name:'Core Reset',price:230,sub:'3 follow-ups bundle'}
    ]
  };

  function animateNumber(el,target){
    const start = parseInt(el.textContent.replace(/[^0-9]/g,''))||0;
    const duration = 600; // ms
    const startTime = performance.now();
    function frame(now){
      const t = Math.min(1,(now-startTime)/duration);
      const v = Math.round(start + (target-start)*t);
      el.textContent = '$'+v;
      if(t<1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  pricingAreas.forEach(area=>{
    const toggle = area.querySelector('.toggle');
    const btns = toggle.querySelectorAll('button');
    const list = area.querySelector('.pricing-list');
    function render(mode){
      const set = pricingData[mode];
      const cards = list.querySelectorAll('.price-card');
      set.forEach((item,i)=>{
        const card = cards[i];
        const priceEl = card.querySelector('.price');
        animateNumber(priceEl,item.price);
        card.querySelector('.price-name').textContent = item.name;
        card.querySelector('.price-sub').textContent = item.sub;
      });
    }
    // wire toggle
    btns.forEach(b=>b.addEventListener('click',function(){
      btns.forEach(x=>x.classList.remove('active'));
      this.classList.add('active');
      const mode = this.getAttribute('data-mode');
      render(mode);
    }));
    // initialize
    render('monthly');
  });

})();
"} 
